import{fold as h}from"./query.min.js";import{buildIndex as f,live as a}from"./derive.min.js";export const LETTERS=[..."ABCDEFGHIJKLMNOPQRSTUVWXYZ","#"],LETTER_ATLAS={cols:9,rows:3};export function letterOf(t){const n=h(t).trim().charAt(0).toUpperCase();return/[A-Z]/.test(n)?n:"#"}export function letterIndex(t){const n=LETTERS.indexOf(t);return n<0?LETTERS.length-1:n}export function cardAngle(t,n=LETTERS.length){return t*2*Math.PI/n}export function spinTo(t,n,o=LETTERS.length){return n-cardAngle(t,o)}export function nearestTurn(t,n){const o=2*Math.PI;return n+o*Math.round((t-n)/o)}export function ringQuad(t,{width:n,inner:o,outer:r},i=LETTERS.length){const e=cardAngle(t,i),c=Math.cos(e),s=Math.sin(e),u=n/2,l=(d,p)=>[d,p*c,p*s];return[l(-u,o),l(u,o),l(u,r),l(-u,r)]}export function ringUvs(t,n=LETTER_ATLAS){const o=t%n.cols,r=Math.floor(t/n.cols),i=o/n.cols,e=(o+1)/n.cols,c=1-r/n.rows,s=1-(r+1)/n.rows;return[[i,s],[e,s],[e,c],[i,c]]}export function contactLine(t){return t?t.title&&t.company?`${t.title} at ${t.company}`:t.title||t.company||"":""}export function peopleText(t){return t.length?t.length===1?t[0]:t.length===2?`${t[0]} and ${t[1]}`:`${t[0]}, ${t[1]} and ${t.length-2} more`:""}export function peopleOf(t,n,o=f(t)){return n.contactIds.map(r=>o.contactsById.get(r)).filter(Boolean)}export function linksOf(t,n,o=f(t)){const r=new Map,i=[];for(const e of t.applications)if(a(e)){e.contactIds.includes(n)&&r.set(e.id,e);for(const c of o.events(e.id))c.withContactIds.includes(n)&&(i.push(c),r.set(e.id,e))}return i.sort((e,c)=>(e.at||"").localeCompare(c.at||"")),{applications:[...r.values()],events:i}}export function involves(t,n,o){return t.contactIds.includes(n)?!0:o.events(t.id).some(r=>r.withContactIds.includes(n))}
